"""Build the assembly guide from the same chapter data as the movie."""
import json
from pathlib import Path
H=Path(__file__).resolve().parent
plan=json.loads((H/'PLAN_MONTAJE.json').read_text())
def stamp(t):return f'{int(t)//60:02d}:{int(t)%60:02d}'
t=3;lines=['# Montaje del instrumento — animación desde Fusion','', 'Revisión propuesta, 3 de noviembre de 2026.','', '## Archivos','', '- Vídeo: `CROSS_MONTAJE_ORDEN_REAL_2026-11-03.mp4` (1920 × 1080, 24 fps, sin audio).', '- Modelo de revisión: `../CROSS_MONTAJE_ACCESIBLE_2026-11-03.f3d`.', '- Original preservado: `CROSS_ANTES_ANIMACION.f3d` y `ESTADO_ORIGINAL_ANTES_CORREGIR_ACCESOS.json`.', '- Vista general de etapas: `SECUENCIA_MONTAJE.png`.', '', 'El vídeo usa imágenes del modelo real de Fusion. Los movimientos se generan con las transformaciones de sus componentes. **No se ha creado una línea de tiempo editable en el espacio Animation de Fusion.** El plan, las posiciones originales y los scripts de generación quedan junto al vídeo.', '', '## Cambios para permitir el montaje','', 'La comprobación de trayectorias mostró que algunas piezas encajaban en su posición final, pero no podían entrar siguiendo una trayectoria recta. Se preparó una revisión que conserva el original guardado por Alex:', '', '1. Travesaño del chasis en X216 convertido en pieza desmontable `P_TRAV216`, con dos M3 × 16 avellanados y dos tuercas cautivas. Se coloca después de la cubierta y antes de la bandeja.', '2. Canal axial inferior para introducir la sonda EC desde atrás: radio 15,3 mm en Y0/Z−60, con alivio lateral para el racor. Espesor geométrico ideal mínimo de 8,7 mm hasta el exterior del chasis; pendiente tolerancia de impresión.', '3. Alivio estrecho para el racor inferior de temperatura, manteniendo la inserción axial.', '4. Paso abierto para la salida lateral del motor y pequeño alivio de la interfaz Atlas. No se desplazan las piezas comerciales.', '5. Extremo de bandeja recortado hasta X371,9 y placa lateral Atlas hasta X371,7 para liberar el aro posterior. Permanecen los apoyos y fijaciones existentes.', '', 'Estos cambios se aplican a las piezas impresas interiores; no cambian tubo, tapas, ranuras de junta, posiciones ópticas ni dimensiones de cierre. La revisión añade una pieza impresa, dos tornillos y dos tuercas. Los 335 BRep incluyen superficies auxiliares y modelos de catálogo: no equivalen al número de piezas de compra.', '', 'La comprobación geométrica es discreta y no sustituye una prueba física. Confirmar acceso de herramientas, juego de montaje y orientación de impresión antes de fabricar.', '', '## Orden y tiempos','', '| Inicio | Paso | Operación |', '| --- | ---: | --- |']
for s in plan['steps']:
 lines.append(f"| {stamp(t)} | {s['number']} | {s['title']} |")
 t+=(s['render_count']/plan['fps_render'] if s['moves'] else 0)+s['hold_seconds']
lines+=['','## Instrucciones de cada etapa','']
for s in plan['steps']:lines.extend([f"### {s['number']:02d}. {s['title']}",'',s['note'],''])
lines+=['## Supuestos y límites','', '- El módulo óptico se prepara en banco: portador, PiCam, AS7265x y LED. Su inserción se representa como una unidad. Apretar sus fijaciones con los ejes ópticos alineados; la película no reproduce cada tornillo.', '- La interfaz Atlas entra lateralmente elevada 8 mm y después desciende. Las conexiones se realizan con acceso abierto.', '- La manguera superior se pasa por la cubierta antes de asentarla. Se deja libre mientras se montan batería, bandeja y placas; se conecta a la bomba al terminar. Las mangueras aparecen en su ruta final: no se simula flexión ni se presupone que atraviesen piezas.', '- Los collares se deslizan axialmente, primero el trasero y luego el delantero, después de arandelas traseras y limitadores. Sus pasos de Ø15 mm dejan pasar los limitadores Ø14; las arandelas anchas Ø22 se colocan fuera de esos pasos. Comprobar las holguras reales de impresión (tubo Ø180 frente a alojamiento Ø180,6).', '- En las etapas 2 y 3 el chasis se hace semitransparente únicamente para mostrar el montaje de las sondas inferiores; su material no cambia.', '- Cables, bridas, algunas fijaciones, adhesivos y herramientas no están representados. Los rótulos indican cuándo deben instalarse.', '- Las juntas se muestran en su geometría de trabajo. No se simula compresión ni se prescribe un par de apriete que todavía no se ha ensayado.', '- Webcam y cabezal peristáltico siguen siendo envolventes aproximadas. El STEP del motor es de familia MOONS, no de la variante exacta; Pi comunitaria y revisión Atlas según el manifiesto de modelos.', '- PCB V8 sigue sin terminar eléctricamente. El vídeo no autoriza fabricar ni energizar la placa.', '- El ensayo de estanqueidad se realiza por separado, con lastre y sin electrónica. No se registra aquí ningún ensayo físico como realizado.', '- Permanecen las incidencias previas del historial de Fusion; no se ha reparado ni ocultado su estado.', '- Documento activo restaurado a la posición armada al terminar cada lote. No se ha guardado una nueva versión en la nube ni se ha hecho commit/push.', '']
(H/'MONTAJE_PASO_A_PASO.md').write_text('\n'.join(lines),encoding='utf-8')
print('Guide generated:',len(plan['steps']),'steps;',round(t,1),'seconds')
